function getSideQuestPromptForNpc(s, npcId) {
  const sqMap = s.worldV3?.sideQuests || {};
  for (const q of _sideQuests.SIDE_QUESTS) {
    if (q.leadNpc !== npcId) continue;
    const st = sqMap[q.id] || {
      started: false,
      stage: 0,
      done: false
    };
    if (st.done) continue;
    const stageObj = q.stages[st.stage];
    if (!stageObj) continue;
    if (stageObj.event.startsWith('sq:')) {
      return {
        quest: q,
        stageObj,
        stageIndex: st.stage
      };
    }
  }
  return null;
}
function listGiftableItems(s) {
  const items = [];
  for (const [k, qty] of Object.entries(s.bag || {})) {
    if (qty > 0) items.push({
      key: k,
      source: 'bag',
      label: `${k.replace(/_/g, ' ')} (×${qty})`
    });
  }
  for (const [k, qty] of Object.entries(s.progression?.materials || {})) {
    if (qty > 0) items.push({
      key: k,
      source: 'materials',
      label: `${k.replace(/_/g, ' ')} (×${qty})`
    });
  }
  return items;
}
